import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Generates the PostgreSQL variant of the Prisma schema from the SQLite source
 * so the two cannot drift. The generated file is not committed.
 *
 * Usage: npm run prisma:prepare-postgres
 */
async function main() {
  const sourcePath = path.resolve("prisma/schema.prisma");
  const targetDir = path.resolve("prisma/postgres");
  const targetPath = path.join(targetDir, "schema.prisma");

  const source = await readFile(sourcePath, "utf8");

  if (!/provider\s*=\s*"sqlite"/.test(source)) {
    throw new Error(
      "prisma/schema.prisma no longer declares provider = \"sqlite\".",
    );
  }

  const generated = source.replace(
    /provider\s*=\s*"sqlite"/,
    'provider = "postgresql"',
  );

  await mkdir(targetDir, { recursive: true });
  await writeFile(
    targetPath,
    `// GENERATED by scripts/prepare-postgres-schema.ts — do not edit.\n${generated}`,
    "utf8",
  );

  console.log(`[prisma] Wrote ${targetPath}`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
